<script lang="ts">import { cart, placeDemoOrder } from '../lib/stores/commerce'; import { navigate } from '../lib/stores/router'; import OrderSummary from '../lib/components/OrderSummary.svelte'; import { LockKeyhole, Check } from 'lucide-svelte'; let name=$state('');let email=$state('');let city=$state('');let consent=$state(false);let submitting=$state(false);let error=$state(''); function submit(e:SubmitEvent){e.preventDefault();if(submitting||!consent)return;submitting=true;try{const order=placeDemoOrder({name:name.trim(),email:email.trim(),city:city.trim()});if(order)navigate(`/order/${order.id}`);else error='Your bag is empty. Add a piece before checking out.';}catch{error='The demo order could not be saved. Please try again.';}finally{submitting=false;}}</script>
<div class="page-heading compact"><div class="breadcrumbs"><a href="#/bag">Your bag</a><span>/</span><span>Demo checkout</span></div><h1>A beautiful next step.</h1><p>Try the complete checkout experience. No payment required.</p></div>
{#if $cart.length}<section class="checkout-layout"><form class="checkout-form" onsubmit={submit}><div class="checkout-alert"><LockKeyhole size={20}/><div><strong>This is a demo checkout.</strong><p>No payment details, full street address, or real purchase is needed. Use sample information.</p></div></div><h2><span>01</span> Your details</h2><div class="form-grid"><label>Name<input autocomplete="off" bind:value={name} required minlength="2" maxlength="80" placeholder="e.g. Anaya Sharma"/></label><label>Email<input type="email" autocomplete="off" bind:value={email} required maxlength="120" placeholder="e.g. anaya@example.com"/></label><label>City<input autocomplete="off" bind:value={city} required minlength="2" maxlength="80" placeholder="e.g. Mumbai"/></label><label>Country<input value="India" readonly/></label></div><h2><span>02</span> Delivery</h2><div class="delivery-option"><Check size={18}/><div><strong>Demo standard delivery</strong><p>Illustrative only. No shipment will be created.</p></div></div><h2><span>03</span> Payment</h2><div class="delivery-option"><LockKeyhole size={18}/><div><strong>No payment — demonstration mode</strong><p>No card information is requested or stored.</p></div></div><label class="consent"><input type="checkbox" bind:checked={consent} required/><span>I understand this creates a sample order saved only in this browser. No purchase, payment, email, or shipment takes place.</span></label>{#if error}<p class="form-error" role="alert">{error}</p>{/if}<button class="button dark full-width" type="submit" disabled={submitting}>{submitting?'Saving demo order…':'Place demo order'} ↗</button><a class="text-link" href="#/bag">← Back to your bag</a></form><OrderSummary checkout/></section>{:else}<section class="empty-state"><h2>Your bag is empty.</h2><p>Add your favourites before trying the checkout.</p><a class="button dark" href="#/shop">Explore the collection</a></section>{/if}
